    function createArbiter(opts) {
        var current = INTENT.IDLE;
        var timer = null;
        var listeners = new Set();
        var active = {};

        var applyNow = () => {
            timer = null;
            var next = highestIntent(active, opts.ruleMeta);
            if (next !== current) {
                current = next;
                listeners.forEach((fn) => fn(next));
            }
        };
        return {
            get current() {
                return current;
            },
            // 感知层每次活跃集合变化时调用
            update(nextActive) {
                active = nextActive;
                var raw = highestIntent(active, opts.ruleMeta);
                if (raw === current) {
                    if (timer) {
                        clearTimeout(timer);
                        timer = null;
                    }
                    return;
                }
                // 动态读 opts（设置保存后无需重建仲裁器即生效）
                var delay =
                    intentPriorityOf(raw, opts.ruleMeta) > intentPriorityOf(current, opts.ruleMeta)
                        ? opts.debounceMs
                        : opts.lingerMs;
                if (timer) clearTimeout(timer);
                timer = setTimeout(applyNow, delay);
            },
            subscribe(fn) {
                listeners.add(fn);
                return () => listeners.delete(fn);
            },
            dispose() {
                if (timer) clearTimeout(timer);
                timer = null;
                listeners.clear();
            },
        };
```

</details>

